#!/bin/bash
# CarMax Extension — Self-contained Mac installer
# Run this script on your Mac to install or update the extension

set -e
EXT_DIR="$HOME/carmax-ext"
echo "📦 Installing CarMax Extension to $EXT_DIR..."
mkdir -p "$EXT_DIR/icons"

# ── Decode and write all extension files ──────────────────────────────────
echo '' | base64 --decode > "$EXT_DIR/manifest.json"
echo '' | base64 --decode > "$EXT_DIR/popup.html"
echo '' | base64 --decode > "$EXT_DIR/popup.js"
echo '' | base64 --decode > "$EXT_DIR/popup.css"
echo '' | base64 --decode > "$EXT_DIR/content.js"
echo '' | base64 --decode > "$EXT_DIR/background.js"
echo 'iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAOklEQVR4nGNgGPwgfMd/8jThwhRpJmgIMZrxGoKmCB8gaAAhQJHtRBlCumZqhwFto5IgoEgzNsNoCQCaDjOAduzp7QAAAABJRU5ErkJggg==' | base64 --decode > "$EXT_DIR/icons/icon16.png"
echo '' | base64 --decode > "$EXT_DIR/icons/icon48.png"
echo '' | base64 --decode > "$EXT_DIR/icons/icon128.png"

echo "✅ Files extracted to $EXT_DIR"

# ── Open Chrome and load the extension ───────────────────────────────────
echo "🌐 Opening Chrome..."

# Check if extension is already loaded
EXT_LOADED=$(osascript -e '
tell application "Google Chrome"
  set extList to {}
  try
    set extJSON to execute front window active tab javascript "
      JSON.stringify(Array.from(document.querySelectorAll(\"extensions-item\")).map(e => e.getAttribute(\"id\")))
    "
  end try
end tell
' 2>/dev/null || echo "")

osascript << 'APPLESCRIPT'
tell application "Google Chrome"
  activate
  
  -- Open extensions page
  set extTab to false
  repeat with w in windows
    repeat with t in tabs of w
      if URL of t starts with "chrome://extensions" then
        set active tab of w to t
        set index of w to 1
        set extTab to true
        exit repeat
      end if
    end repeat
    if extTab then exit repeat
  end repeat
  
  if not extTab then
    tell front window
      set newTab to make new tab with properties {URL: "chrome://extensions/"}
      set active tab to newTab
    end tell
  end if
  
  delay 2
  
  -- Enable developer mode and click load unpacked via keyboard shortcut
  tell front window
    tell active tab
      execute javascript "
        const manager = document.querySelector('extensions-manager');
        if (manager && manager.shadowRoot) {
          const toolbar = manager.shadowRoot.querySelector('extensions-toolbar');
          if (toolbar && toolbar.shadowRoot) {
            const toggle = toolbar.shadowRoot.querySelector('#devMode');
            if (toggle && !toggle.checked) toggle.click();
          }
        }
      "
    end tell
  end tell
  
  delay 1
  tell front window
    tell active tab
      execute javascript "
        const manager = document.querySelector('extensions-manager');
        if (manager && manager.shadowRoot) {
          const toolbar = manager.shadowRoot.querySelector('extensions-toolbar');
          if (toolbar && toolbar.shadowRoot) {
            const loadBtn = toolbar.shadowRoot.querySelector('#loadUnpacked');
            if (loadBtn) loadBtn.click();
          }
        }
      "
    end tell
  end tell
end tell
APPLESCRIPT

echo ""
echo "════════════════════════════════════════════"
echo "  Chrome открыт на странице расширений."
echo ""
echo "  Если появился диалог выбора папки —"
echo "  выберите папку: $HOME/carmax-ext"
echo ""
echo "  Если диалог не появился:"
echo "  1. Включите «Режим разработчика»"
echo "  2. Нажмите «Загрузить распакованное»"
echo "  3. Выберите: $HOME/carmax-ext"
echo "════════════════════════════════════════════"
